create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,name text,avatar_url text,role text not null default 'user' check(role in ('user','admin')),plan text not null default 'free',created_at timestamptz not null default now());
create table if not exists public.pages(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references public.profiles(id) on delete cascade,username text not null unique,name text not null,bio text,avatar_url text,language text not null default 'ar',template int not null default 1 check(template between 1 and 8),theme jsonb not null default '{}'::jsonb,sections jsonb not null default '[]'::jsonb,published boolean not null default false,seo_title text,seo_description text,noindex boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),page_id uuid not null references public.pages(id) on delete cascade,name text not null,description text,price numeric(12,2) not null default 0,currency text not null default 'USD',image_url text,sku text,stock int,category text,product_url text,whatsapp_enabled boolean not null default true,active boolean not null default true,featured boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.services(id uuid primary key default gen_random_uuid(),page_id uuid not null references public.pages(id) on delete cascade,name text not null,description text,price numeric(12,2),duration_minutes int,image_url text,booking_url text,whatsapp_enabled boolean not null default true,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.analytics_events(id bigint generated always as identity primary key,page_id uuid not null references public.pages(id) on delete cascade,section_id text,event_type text not null,target text,referrer text,user_agent text,created_at timestamptz not null default now());
create index if not exists analytics_page_created_idx on public.analytics_events(page_id,created_at desc);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email) values(new.id,new.email) on conflict do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security;alter table public.pages enable row level security;alter table public.products enable row level security;alter table public.services enable row level security;alter table public.analytics_events enable row level security;
drop policy if exists profiles_self on public.profiles;create policy profiles_self on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);
drop policy if exists pages_public on public.pages;create policy pages_public on public.pages for select using(published=true or auth.uid()=user_id);
drop policy if exists pages_owner on public.pages;create policy pages_owner on public.pages for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists products_public on public.products;create policy products_public on public.products for select using(exists(select 1 from pages p where p.id=page_id and (p.published=true or p.user_id=auth.uid())));
drop policy if exists products_owner on public.products;create policy products_owner on public.products for all using(exists(select 1 from pages p where p.id=page_id and p.user_id=auth.uid())) with check(exists(select 1 from pages p where p.id=page_id and p.user_id=auth.uid()));
drop policy if exists services_public on public.services;create policy services_public on public.services for select using(exists(select 1 from pages p where p.id=page_id and (p.published=true or p.user_id=auth.uid())));
drop policy if exists services_owner on public.services;create policy services_owner on public.services for all using(exists(select 1 from pages p where p.id=page_id and p.user_id=auth.uid())) with check(exists(select 1 from pages p where p.id=page_id and p.user_id=auth.uid()));
create policy analytics_insert on public.analytics_events for insert with check(true);create policy analytics_owner_read on public.analytics_events for select using(exists(select 1 from pages p where p.id=page_id and p.user_id=auth.uid()));
